import React from 'react';

const Carousel3D = ({ movies = [], currentIndex, setCurrentIndex }) => {
  const displayMovies = movies.length > 0 ? movies : [
    { id: 0, title: "Dune 2", poster_path: "" },
    { id: 1, title: "Wicked", poster_path: "" },
    { id: 2, title: "Interstellar", poster_path: "" },
    { id: 3, title: "Avatar", poster_path: "" },
    { id: 4, title: "Joker", poster_path: "" },
  ];

  const total = displayMovies.length;

  const handleNext = () => setCurrentIndex((prev) => (prev + 1) % total);
  const handlePrev = () => setCurrentIndex((prev) => (prev - 1 + total) % total);

  return (
    <div className="relative w-full py-6 flex flex-col items-center justify-center bg-[#0b090e] overflow-hidden">
      
      {/* 은은한 네온 글로우 효과 */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[250px] bg-purple-600/10 rounded-full blur-[120px] pointer-events-none" />

      {/* 3D 스테이지 영역 */}
      <div 
        className="relative w-full max-w-5xl h-[380px] flex items-center justify-center"
        style={{ perspective: '1400px' }}
      >
        {displayMovies.map((movie, index) => {
          let offset = (index - currentIndex + total) % total;
          if (offset > total / 2) offset -= total;

          const translateX = offset * 200;
          const translateZ = -Math.abs(offset) * 75;
          const rotateY = offset * -18;
          const scale = Math.max(1 - Math.abs(offset) * 0.1, 0.75);
          const opacity = Math.abs(offset) > 2.5 ? 0 : 1;

          return (
            <div
              key={movie.id || index}
              onClick={() => setCurrentIndex(index)}
              style={{
                transform: `translateX(${translateX}px) translateZ(${translateZ}px) rotateY(${rotateY}deg) scale(${scale})`,
                zIndex: total - Math.abs(offset),
                opacity: opacity,
                pointerEvents: opacity === 0 ? 'none' : 'auto',
                transition: 'all 0.5s cubic-bezier(0.25, 1, 0.5, 1)',
              }}
              className={`absolute w-48 h-72 rounded-xl overflow-hidden cursor-pointer shadow-2xl border bg-zinc-900 ${
                offset === 0 
                  ? 'border-purple-500 shadow-[0_0_35px_rgba(168,85,247,0.35)]' 
                  : 'border-white/10 brightness-75'
              }`}
            >
              {movie.poster_path ? (
                <img 
                  src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`} 
                  alt={movie.title || 'Movie Poster'} 
                  className="w-full h-full object-cover pointer-events-none" 
                />
              ) : (
                <div className="w-full h-full bg-zinc-800 flex flex-col items-center justify-center text-xs text-zinc-400 p-4 text-center">
                  <span className="font-bold text-white text-sm mb-1">{movie.title}</span>
                  <span>포스터 이미지</span>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* 네비게이션 화살표 및 인디케이터 */}
      <div className="flex items-center gap-6 mt-4 z-20">
        <button 
          onClick={handlePrev} 
          className="w-9 h-9 rounded-full bg-white/10 text-white flex items-center justify-center hover:bg-white/20 transition cursor-pointer font-bold border border-white/10"
        >
          &larr;
        </button>
        <div className="flex gap-2">
          {displayMovies.map((_, idx) => (
            <span 
              key={idx}
              onClick={() => setCurrentIndex(idx)}
              className={`h-1.5 rounded-full cursor-pointer transition-all ${
                idx === currentIndex ? 'bg-purple-500 w-6' : 'bg-white/20 w-1.5'
              }`}
            />
          ))}
        </div>
        <button 
          onClick={handleNext} 
          className="w-9 h-9 rounded-full bg-white/10 text-white flex items-center justify-center hover:bg-white/20 transition cursor-pointer font-bold border border-white/10"
        >
          &rarr;
        </button>
      </div>

    </div>
  );
};

export default Carousel3D;
